package com.securebiz.report.repository;
import com.securebiz.report.api.DashboardDtos.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.stereotype.Repository;import java.math.BigDecimal;import java.sql.*;import java.time.*;import java.util.*;
@Repository public class DashboardRepository{private final JdbcClient jdbc;public DashboardRepository(JdbcClient jdbc){this.jdbc=jdbc;}
 public MetricSummary summary(Instant from,Instant to){var sales=jdbc.sql("SELECT COALESCE(sum(total),0) revenue,count(*) orders FROM orders WHERE status IN('COMPLETED','PARTIALLY_RETURNED','RETURNED') AND created_at>=:from AND created_at<:to").param("from",Timestamp.from(from)).param("to",Timestamp.from(to)).query((r,n)->new Sales(r.getBigDecimal("revenue"),r.getLong("orders"))).single();BigDecimal inventory=jdbc.sql("SELECT COALESCE(sum(i.quantity*v.cost_price),0) FROM inventory i JOIN product_variants v ON v.id=i.product_variant_id").query(BigDecimal.class).single();BigDecimal purchases=jdbc.sql("SELECT COALESCE(sum(gri.quantity*poi.unit_cost),0) FROM goods_receipts gr JOIN goods_receipt_items gri ON gri.goods_receipt_id=gr.id JOIN purchase_order_items poi ON poi.id=gri.purchase_order_item_id WHERE gr.received_at>=:from AND gr.received_at<:to").param("from",Timestamp.from(from)).param("to",Timestamp.from(to)).query(BigDecimal.class).single();BigDecimal aov=sales.orders()==0?BigDecimal.ZERO:sales.revenue().divide(BigDecimal.valueOf(sales.orders()),4,java.math.RoundingMode.HALF_UP);return new MetricSummary(sales.revenue(),sales.orders(),aov,inventory,purchases);}
 public List<TimePoint> trend(Instant from,Instant to){return jdbc.sql("SELECT created_at::date AS report_day,COALESCE(sum(total),0) revenue,count(*) orders FROM orders WHERE status IN('COMPLETED','PARTIALLY_RETURNED','RETURNED') AND created_at>=:from AND created_at<:to GROUP BY created_at::date ORDER BY report_day").param("from",Timestamp.from(from)).param("to",Timestamp.from(to)).query((r,n)->new TimePoint(r.getObject("report_day",LocalDate.class),r.getBigDecimal("revenue"),r.getLong("orders"))).list();}
 public List<NamedValue> topProducts(Instant from,Instant to){return jdbc.sql("SELECT oi.product_name name,sum(oi.quantity) value FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE o.status IN('COMPLETED','PARTIALLY_RETURNED','RETURNED') AND o.created_at>=:from AND o.created_at<:to GROUP BY oi.product_name ORDER BY value DESC LIMIT 10").param("from",Timestamp.from(from)).param("to",Timestamp.from(to)).query((r,n)->new NamedValue(r.getString("name"),r.getBigDecimal("value"))).list();}
 public List<NamedValue> byWarehouse(Instant from,Instant to){return jdbc.sql("SELECT w.name,sum(o.total) value FROM orders o JOIN warehouses w ON w.id=o.warehouse_id WHERE o.status IN('COMPLETED','PARTIALLY_RETURNED','RETURNED') AND o.created_at>=:from AND o.created_at<:to GROUP BY w.name ORDER BY value DESC").param("from",Timestamp.from(from)).param("to",Timestamp.from(to)).query((r,n)->new NamedValue(r.getString("name"),r.getBigDecimal("value"))).list();}
 public List<EmployeeRevenue> byEmployee(Instant from,Instant to){return jdbc.sql("SELECT COALESCE(e.full_name,u.username) name,sum(o.total) revenue,count(*) orders FROM orders o JOIN users u ON u.id=o.created_by LEFT JOIN employees e ON e.user_id=u.id WHERE o.status IN('COMPLETED','PARTIALLY_RETURNED','RETURNED') AND o.created_at>=:from AND o.created_at<:to GROUP BY COALESCE(e.full_name,u.username) ORDER BY revenue DESC LIMIT 20").param("from",Timestamp.from(from)).param("to",Timestamp.from(to)).query((r,n)->new EmployeeRevenue(r.getString("name"),r.getBigDecimal("revenue"),r.getLong("orders"))).list();}
 public List<PurchasePoint> purchaseTrend(Instant from,Instant to){return jdbc.sql("SELECT gr.received_at::date AS report_day,sum(gri.quantity*poi.unit_cost) received_value,count(DISTINCT gr.id) receipts FROM goods_receipts gr JOIN goods_receipt_items gri ON gri.goods_receipt_id=gr.id JOIN purchase_order_items poi ON poi.id=gri.purchase_order_item_id WHERE gr.received_at>=:from AND gr.received_at<:to GROUP BY gr.received_at::date ORDER BY report_day").param("from",Timestamp.from(from)).param("to",Timestamp.from(to)).query((r,n)->new PurchasePoint(r.getObject("report_day",LocalDate.class),r.getBigDecimal("received_value"),r.getLong("receipts"))).list();}
 public List<StockMovement> stockMovements(Instant from,Instant to){return jdbc.sql("SELECT st.type,sum(sti.quantity_delta) quantity FROM stock_transactions st JOIN stock_transaction_items sti ON sti.stock_transaction_id=st.id WHERE st.occurred_at>=:from AND st.occurred_at<:to GROUP BY st.type ORDER BY st.type").param("from",Timestamp.from(from)).param("to",Timestamp.from(to)).query((r,n)->new StockMovement(r.getString("type"),r.getBigDecimal("quantity"))).list();}
 public List<LowStock> lowStock(){return jdbc.sql("SELECT v.sku,p.name product,w.name warehouse,i.quantity,i.reorder_level FROM inventory i JOIN product_variants v ON v.id=i.product_variant_id JOIN products p ON p.id=v.product_id JOIN warehouses w ON w.id=i.warehouse_id WHERE i.quantity<=i.reorder_level ORDER BY (i.quantity-i.reorder_level),v.sku LIMIT 50").query((r,n)->new LowStock(r.getString("sku"),r.getString("product"),r.getString("warehouse"),r.getBigDecimal("quantity"),r.getBigDecimal("reorder_level"))).list();}
 private record Sales(BigDecimal revenue,long orders){}
}
